/**
 * Writes supabase/seed.sql from src/data/seed.ts so the demo catalogue and the real
 * database start with the same products. Run with: npm run seed:sql
 */
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { seedCategories, seedCollections, seedProducts } from '../src/data/seed';

const q = (v: string | null) => (v === null ? 'null' : `'${v.replace(/'/g, "''")}'`);
const n = (v: number | null) => (v === null ? 'null' : String(v));

const lines: string[] = [
  '-- Generated by scripts/generate-seed-sql.ts — do not edit by hand.',
  '-- Starter catalogue. Image URLs are relative paths to files bundled with the app.',
  '-- Safe to re-run: existing categories, collections and products (by SKU) are skipped.',
  '',
  '-- Main categories first, then sub-categories linked to their parent by slug.',
  'insert into public.categories (slug, name, image_url, sort_order) values',
  seedCategories
    .map((c, i) => ({ c, i }))
    .filter(({ c }) => !c.parent)
    .map(({ c, i }) => `  (${q(c.slug)}, ${q(c.name)}, ${q(c.image)}, ${i})`)
    .join(',\n') + '\non conflict (slug) do nothing;',
  '',
  'insert into public.categories (slug, name, image_url, sort_order, parent_id) values',
  seedCategories
    .map((c, i) => ({ c, i }))
    .filter(({ c }) => c.parent)
    .map(({ c, i }) => `  (${q(c.slug)}, ${q(c.name)}, ${q(c.image)}, ${i}, (select id from public.categories where slug = ${q(c.parent)}))`)
    .join(',\n') + '\non conflict (slug) do nothing;',
  '',
  'insert into public.collections (slug, name, tagline, image_url, sort_order) values',
  seedCollections.map((c, i) => `  (${q(c.slug)}, ${q(c.name)}, ${q(c.tagline)}, ${q(c.image)}, ${i})`).join(',\n') +
    '\non conflict (slug) do nothing;',
  ''
];

for (const p of seedProducts) {
  lines.push(
    `with p as (
  insert into public.products (sku, slug, name, description, category_id, collection_id, style, metal, purity,
    weight_min, weight_max, make, gross_weight, stone_weight, net_weight, quantity, stone, size, availability, price, show_price, specifications, is_new, is_featured,
    is_published, views, created_at, updated_at)
  values (${q(p.sku)}, ${q(p.slug)}, ${q(p.name)}, ${q(p.description)},
    (select id from public.categories where slug = ${q(p.category)}),
    (select id from public.collections where slug = ${q(p.collection)}),
    ${q(p.style)}, ${q(p.metal)}, ${q(p.purity)}, ${n(p.weightMin)}, ${n(p.weightMax)},
    ${q(p.make)}, ${n(p.grossWeight)}, ${n(p.stoneWeight)}, ${n(p.netWeight)}, ${p.quantity}, ${q(p.stone)}, ${q(p.size)},
    ${q(p.availability)}, ${n(p.price)}, ${p.showPrice}, ${q(JSON.stringify(p.specifications))}::jsonb,
    ${p.isNew}, ${p.isFeatured}, true, ${p.views}, now() - interval '${p.ageDays} days', now() - interval '${p.ageDays} days')
  on conflict (sku) do nothing
  returning id
)
insert into public.product_images (product_id, url, alt, sort_order)
select p.id, img.url, ${q(p.name)}, img.ord - 1
from p, unnest(array[${p.images.map(q).join(', ')}]) with ordinality as img(url, ord);
`
  );
}

const seedSql = lines.join('\n') + '\n';
const dir = (f: string) => fileURLToPath(new URL(`../supabase/${f}`, import.meta.url));
writeFileSync(dir('seed.sql'), seedSql);

// One file to paste into the Supabase SQL editor: every migration, then the seed.
const migrations = readdirSync(dir('migrations'))
  .filter((f) => f.endsWith('.sql'))
  .sort()
  .map((f) => `-- ===== migrations/${f} =====\n${readFileSync(dir(`migrations/${f}`), 'utf8')}`);
writeFileSync(
  dir('setup.sql'),
  [
    '-- Sanskruti Jewels: complete database setup (schema + starter catalogue).',
    '-- Generated by scripts/generate-seed-sql.ts — do not edit by hand.',
    '-- Paste this WHOLE file into a NEW, EMPTY query in the Supabase SQL editor and click Run.',
    '-- It is safe to run more than once.',
    '',
    ...migrations,
    '-- ===== seed.sql =====',
    seedSql
  ].join('\n')
);
console.log(`Wrote ${seedProducts.length} products to seed.sql and setup.sql`);
